// STARFIELD
// ═══════════════════════════════════════════════════
function Starfield() {
  const ref = useRef(null);
  useEffect(() => {
    const c = ref.current; if (!c) return;
    const ctx = c.getContext("2d");
    let w = c.width = window.innerWidth, h = c.height = window.innerHeight;
    const stars = Array.from({ length: 280 }, () => ({
      x: Math.random() * w, y: Math.random() * h,
      r: Math.random() * 1.3 + 0.15, a: Math.random() * 0.6 + 0.08,
      sp: Math.random() * 0.0004 + 0.0001, ph: Math.random() * Math.PI * 2,
    }));
    let raf;
    const draw = (t) => {
      ctx.clearRect(0, 0, w, h);
      stars.forEach(s => {
        const tw = Math.sin(t * s.sp * 60 + s.ph) * 0.35 + 0.65;
        ctx.beginPath(); ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(220,225,240,${s.a * tw})`;
        ctx.fill();
      });
      stars.slice(0, 8).forEach(s => {
        const g = Math.sin(t * 0.0008 + s.ph) * 0.5 + 0.5;
        ctx.beginPath(); ctx.arc(s.x, s.y, s.r + 1.5, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(255,255,255,${0.06 * g})`;
        ctx.fill();
        if (s.a > 0.4) {
          ctx.strokeStyle = `rgba(255,255,255,${0.04 * g})`;
          ctx.lineWidth = 0.5;
          ctx.beginPath(); ctx.moveTo(s.x - 4, s.y); ctx.lineTo(s.x + 4, s.y); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(s.x, s.y - 4); ctx.lineTo(s.x, s.y + 4); ctx.stroke();
        }
      });
      raf = requestAnimationFrame(draw);
    };
    raf = requestAnimationFrame(draw);
    const resize = () => { w = c.width = window.innerWidth; h = c.height = window.innerHeight; };
    window.addEventListener("resize", resize);
    return () => { cancelAnimationFrame(raf); window.removeEventListener("resize", resize); };
  }, []);
  return <canvas ref={ref} style={{ position: "fixed", inset: 0, zIndex: 0, pointerEvents: "none" }} />;
}

