// ═══════════════════════════════════════════════════
// GAUGE
// ═══════════════════════════════════════════════════
function ValuationGauge({ value, size = 160, label, type = "valuation" }) {
  const ref = useRef(null);
  const [av, setAv] = useState(0);
  useEffect(() => { const s = performance.now(); const run = (n) => { const p = Math.min((n - s) / 1200, 1); setAv((1 - Math.pow(1 - p, 3)) * value); if (p < 1) requestAnimationFrame(run); }; requestAnimationFrame(run); }, [value]);
  useEffect(() => {
    const c = ref.current; if (!c) return;
    const ctx = c.getContext("2d"); const d = window.devicePixelRatio || 1;
    c.width = size * d; c.height = size * 0.7 * d; ctx.scale(d, d);
    c.style.width = size + "px"; c.style.height = size * 0.7 + "px";
    const cx = size / 2, cy = size * 0.58, r = size * 0.38, lw = size * 0.055;
    ctx.beginPath(); ctx.arc(cx, cy, r, Math.PI, 2 * Math.PI); ctx.strokeStyle = "rgba(255,255,255,0.04)"; ctx.lineWidth = lw; ctx.lineCap = "round"; ctx.stroke();
    const segs = 60, va = Math.PI + (av / 100) * Math.PI;
    for (let i = 0; i < segs; i++) { const sA = Math.PI + (i / segs) * Math.PI; if (sA > va) break; const eA = Math.min(Math.PI + ((i + 1) / segs) * Math.PI, va); const t = i / segs; let col; if (t < 0.33) col = `rgba(251,113,133,${0.5 + t})`; else if (t < 0.66) col = `rgba(251,191,36,${0.5 + t * 0.3})`; else col = `rgba(74,222,128,${0.5 + t * 0.3})`; ctx.beginPath(); ctx.arc(cx, cy, r, sA, eA + 0.02); ctx.strokeStyle = col; ctx.lineWidth = lw; ctx.lineCap = "round"; ctx.stroke(); }
    const nA = Math.PI + (av / 100) * Math.PI; ctx.save(); ctx.translate(cx, cy); ctx.rotate(nA); ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(-(r - lw), 0); ctx.strokeStyle = "rgba(240,244,248,0.8)"; ctx.lineWidth = 1.5; ctx.lineCap = "round"; ctx.stroke(); ctx.restore();
    ctx.beginPath(); ctx.arc(cx, cy, 3, 0, Math.PI * 2); ctx.fillStyle = "#fff"; ctx.fill();
    ctx.beginPath(); ctx.arc(cx, cy, 5.5, 0, Math.PI * 2); ctx.strokeStyle = "rgba(255,255,255,0.15)"; ctx.lineWidth = 0.8; ctx.stroke();
  }, [av, size, type]);
  const getLabel = () => { if (type === "valuation") return value < 33 ? "Overvalued" : value < 66 ? "Fairly Valued" : "Undervalued"; if (type === "sentiment") return value < 33 ? "Bearish" : value < 66 ? "Neutral" : "Bullish"; return value < 33 ? "Sell" : value < 66 ? "Hold" : "Buy"; };
  const getColor = () => value < 33 ? T.red : value < 66 ? T.amber : T.green;
  return (<div style={{ textAlign: "center" }}><canvas ref={ref} /><div style={{ marginTop: -6 }}><span style={{ fontSize: size * 0.095, fontWeight: 700, color: getColor(), letterSpacing: "0.06em", textTransform: "uppercase", fontFamily: T.mono }}>{getLabel()}</span></div>{label && <div style={{ fontSize: 9, color: T.textDim, marginTop: 3, textTransform: "uppercase", letterSpacing: "0.18em", fontFamily: T.mono, fontWeight: 500 }}>{label}</div>}</div>);
}

function Sparkline({ data, color = T.green, width = 80, height = 30 }) {
  const pts = data.map((v, i) => { const mn = Math.min(...data), mx = Math.max(...data), rg = mx - mn || 1; return `${(i / (data.length - 1)) * width},${height - ((v - mn) / rg) * height}`; }).join(" ");
  return (<svg width={width} height={height} style={{ display: "block" }}><polyline points={pts} fill="none" stroke={color} strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" opacity="0.7" /></svg>);
}

function StockCard({ stock, onClick }) {
  const col = stock.overallScore >= 66 ? T.green : stock.overallScore >= 33 ? T.amber : T.red;
  const lbl = stock.overallScore >= 66 ? "BUY" : stock.overallScore >= 33 ? "HOLD" : "SELL";
  return (
    <div onClick={onClick} style={{ background: T.bgCard, border: `1px solid ${T.border}`, borderRadius: 16, padding: 24, cursor: "pointer", transition: "all 0.3s ease", position: "relative", backdropFilter: "blur(12px)" }} onMouseEnter={e => { e.currentTarget.style.borderColor = T.borderHover; e.currentTarget.style.transform = "translateY(-3px)"; e.currentTarget.style.boxShadow = "0 8px 40px rgba(255,255,255,0.03)"; }} onMouseLeave={e => { e.currentTarget.style.borderColor = T.border; e.currentTarget.style.transform = "translateY(0)"; e.currentTarget.style.boxShadow = "none"; }}>
      <div style={{ position: "absolute", top: 16, right: 16, background: col, color: "#020204", fontWeight: 800, fontSize: 10, padding: "3px 10px", borderRadius: 20, letterSpacing: "0.12em", fontFamily: T.mono }}>{lbl}</div>
      <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 16 }}>
        <div style={{ width: 42, height: 42, borderRadius: 10, background: T.accentSubtle, display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 800, fontSize: 12, color: T.accent, fontFamily: T.mono, border: `1px solid ${T.border}` }}>{stock.ticker.slice(0, 2)}</div>
        <div><div style={{ fontWeight: 700, fontSize: 15, color: T.text }}>{stock.ticker}</div><div style={{ fontSize: 11, color: T.textDim }}>{stock.name}</div></div>
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", marginBottom: 20 }}>
        <div><div style={{ fontSize: 22, fontWeight: 700, color: T.text, fontFamily: T.mono }}>${stock.price.toFixed(2)}</div><div style={{ fontSize: 12, fontWeight: 600, color: stock.changePct >= 0 ? T.green : T.red, fontFamily: T.mono }}>{stock.changePct >= 0 ? "+" : ""}{stock.changePct.toFixed(2)}%</div></div>
        <Sparkline data={[85, 82, 88, 91, 87, 93, 89, 95, 92, 97, 94, 100].map(v => v * stock.price / 100)} color={stock.changePct >= 0 ? T.green : T.red} />
      </div>
      <div style={{ display: "flex", justifyContent: "space-around" }}><ValuationGauge value={stock.valuationScore} size={100} label="Value" type="valuation" /><ValuationGauge value={stock.sentimentScore} size={100} label="Sentiment" type="sentiment" /></div>
    </div>
  );
}

